\begin{ex}%[9H4H2-1]
Cho tam giác ${ABC}$ vuông tại ${A}$

 a) biết $AC=9$, $\widehat{B} = 60^{\circ}$. Tính ${AB}$.

b) biết $AB=4$, $\widehat{B} = 30^{\circ}$. Tính ${AC}$.
\loigiai{
a) Xét $\triangle ABC$ vuông tại $A$: $AB = AC \cdot \cot B = 9 \cdot \cot 60^\circ = 3 \sqrt{3}$.\\
b) Xét $\triangle ABC$ vuông tại $A$: $AC = AB \cdot \tan B = 4 \cdot \tan 30^\circ = \frac{4 \sqrt{3}}{3}$.
}\end{ex}

